import { useState, type FormEvent } from 'react';
import {
  JxButton,
  JxInputField,
  JxToastViewport,
  useJxToastQueue,
} from '@jinx-ui/react';

export default function SubscribeForm() {
  const toasts = useJxToastQueue();
  const [email, setEmail] = useState('');

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    toasts.push({
      title: 'Готово',
      message: `Письмо отправлено на ${email}`,
      variant: 'success',
    });
    setEmail('');
  };

  return (
    <form
      onSubmit={handleSubmit}
      style={{ display: 'flex', flexDirection: 'column', gap: '12px', maxWidth: '360px' }}
    >
      <JxInputField
        label="Электронная почта"
        type="email"
        required
        placeholder="name@example.com"
        helperText="Присылаем письма не чаще раза в неделю"
        value={email}
        onChange={(event) => setEmail(event.target.value)}
      />
      <JxButton type="submit" variant="primary">
        Подписаться
      </JxButton>
      <JxToastViewport
        items={toasts.items}
        onDismiss={toasts.dismiss}
        position="bottom-right"
      />
    </form>
  );
}

